on conflict (tel_norm) do update set
  nombre    = coalesce(nullif(clientes.nombre, ''), excluded.nombre),
  ciudad    = coalesce(nullif(clientes.ciudad, ''), excluded.ciudad),
  direccion = coalesce(nullif(clientes.direccion, ''), excluded.direccion),
  nota      = case when clientes.nota = '' then excluded.nota
                   when excluded.nota = '' or position(excluded.nota in clientes.nota) > 0 then clientes.nota
                   else clientes.nota || ' · ' || excluded.nota end;

select count(*) as clientes_registrados from public.clientes;
